            let loadTimer = 0;
            const finish = (ok, error = null) => {
              if (settled) return;
              settled = true;
              if (loadTimer) {
                window.clearTimeout(loadTimer);
                loadTimer = 0;
              }
              pdfEls.image.onload = null;
              pdfEls.image.onerror = null;
              if (ok) resolve();
              else reject(error || new Error(isPictureMode ? "Could not render picture." : "Could not render PDF image."));
            };
