            void loadPdfSharedAudioMarkers({ clientSource: "pdf_render_audio" });
            void loadPdfAiRegionNotices({ clientSource: "pdf_render_notices" });
            void loadPdfAiRegionQuestions({ clientSource: "pdf_render_questions" });
